// SBOM (sbom.cdx.json, generated by build.mjs) and the rules of the library check (vendor.mjs --check).
// No network: the check's facts are given here; the live check runs monthly in vendor-check.yml.
import { test, expect } from '@playwright/test';
import { readFileSync, readdirSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { posix } from 'node:path';
import { assessHealth, vulnSeverity, vulnBlocks } from '../scripts/lib.mjs';
import { snapshot } from '../scripts/sbom.mjs';

const vendor = JSON.parse(readFileSync('scripts/vendor.json', 'utf8'));
const bom = JSON.parse(readFileSync('sbom.cdx.json', 'utf8'));
const filesIn = dir => readdirSync(dir, { withFileTypes: true })
  .flatMap(e => e.isDirectory() ? filesIn(posix.join(dir, e.name)) : [posix.join(dir, e.name)]);

test.describe('SBOM', () => {
  test('is CycloneDX 1.6, deterministic: no timestamp, serial number derived from the content', () => {
    expect(bom.bomFormat).toBe('CycloneDX');
    expect(bom.specVersion).toBe('1.6');
    expect(bom.metadata.timestamp).toBeUndefined();
    // actions/attest (pages.yml) only accepts CycloneDX with bomFormat, specVersion and serialNumber
    const { $schema, bomFormat, specVersion, serialNumber, version, ...body } = bom;
    const h = createHash('sha256').update(JSON.stringify(body)).digest('hex');
    expect(serialNumber).toMatch(/^urn:uuid:[0-9a-f]{8}-[0-9a-f]{4}-8[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/);
    expect(serialNumber.replace(/-/g, '').slice(9, 17)).toBe(h.slice(0, 8));
  });

  test('lists every library with purl, licence, npm integrity and the hash of every shipped file', () => {
    const libs = bom.components.filter(c => c.type === 'library');
    expect(libs.map(c => c['bom-ref']).sort()).toEqual(Object.keys(vendor).map(n => `vendor:${n}`).sort());
    for (const [name, e] of Object.entries(vendor)) {
      const c = libs.find(x => x['bom-ref'] === `vendor:${name}`);
      expect(c.version, name).toBe(e.version);
      expect(c.purl).toBe(`pkg:npm/${e.package.replace('@', '%40')}@${e.version}`);
      expect(c.licenses).toEqual([{ license: { id: e.license } }]);
      const dist = c.externalReferences.find(r => r.type === 'distribution');
      expect(dist.url).toMatch(/^https:\/\/registry\.npmjs\.org\/.+\.tgz$/);
      const [algo, b64] = e.integrity.split('-');
      expect(dist.hashes).toEqual([{ alg: 'SHA-512', content: Buffer.from(b64, 'base64').toString('hex') }]);
      expect(algo).toBe('sha512');
      // exactly the files on disk, each with its SHA-256
      const files = filesIn(`assets/vendor/${name}`).sort();
      expect(c.components.map(f => f.name)).toEqual(files);
      for (const f of c.components) {
        expect(f.hashes[0]).toEqual({ alg: 'SHA-256', content: createHash('sha256').update(readFileSync(f.name)).digest('hex') });
      }
    }
  });

  test('links apps to the libraries they load', () => {
    const refs = new Set([...bom.components.map(c => c['bom-ref']), 'site']);
    for (const d of bom.dependencies) {
      expect(refs.has(d.ref), d.ref).toBe(true);
      for (const r of d.dependsOn) expect(refs.has(r), r).toBe(true);
    }
    const deps = ref => bom.dependencies.find(d => d.ref === ref).dependsOn;
    // independently known: PDF bearbeiten uses pdf.js and pdf-lib, the brew calculator KaTeX
    expect(deps('app:pdf-edit')).toEqual(expect.arrayContaining(['vendor:pdfjs', 'vendor:pdf-lib']));
    expect(deps('app:brew-calculator')).toEqual(['vendor:katex']);
    expect(deps('vendor:transformers')).toEqual(['vendor:onnxruntime-web']);
    // every library is reachable from the site
    const reach = new Set(), walk = r => { if (reach.has(r)) return; reach.add(r); deps(r).forEach(walk); };
    walk('site');
    for (const n of Object.keys(vendor)) expect(reach.has(`vendor:${n}`), n).toBe(true);
  });

  test('dependency-graph snapshot contains every library as runtime dependency', () => {
    const s = snapshot(bom, { GITHUB_SHA: 'a'.repeat(40), GITHUB_REF: 'refs/heads/main', GITHUB_RUN_ID: '1' });
    const resolved = s.manifests['scripts/vendor.json'].resolved;
    expect(Object.keys(resolved)).toHaveLength(Object.keys(vendor).length);
    expect(resolved['pkg:npm/%40cantoo/pdf-lib@' + vendor['pdf-lib'].version]).toMatchObject({ relationship: 'direct', scope: 'runtime' });
  });
});

test.describe('library maintenance rules', () => {
  const now = Date.parse('2026-10-31T00:00:00Z');
  const fresh = { deprecated: '', latestDeprecated: '', archived: false, lastRelease: '2026-09-15T00:00:00Z', lastCommit: '2026-10-20T00:00:00Z', maintained: 10, repo: 'github.com/a/b' };

  test('a maintained library passes', () => {
    expect(assessHealth(fresh, { now })).toEqual({ level: 'ok', reasons: [] });
  });

  test('the original pdf-lib fails: last release Nov 2021, no activity', () => {
    // facts as reported by npm/deps.dev for pdf-lib 1.17.1 (no GitHub data → Scorecard decides)
    const h = assessHealth({ ...fresh, lastRelease: '2021-11-06T22:29:49Z', lastCommit: null, maintained: 0 }, { now });
    expect(h.level).toBe('fail');
    expect(h.reasons[0]).toBe('seit 59 Monaten kein Release und in den letzten 90 Tagen keine Commits');
  });

  test('deprecated or archived fails at once', () => {
    expect(assessHealth({ ...fresh, deprecated: 'use x instead' }, { now }).level).toBe('fail');
    expect(assessHealth({ ...fresh, latestDeprecated: 'no longer supported' }, { now }).level).toBe('fail');
    expect(assessHealth({ ...fresh, archived: true }, { now }).level).toBe('fail');
  });

  test('old release with recent commits only warns; 12–24 months warns', () => {
    expect(assessHealth({ ...fresh, lastRelease: '2023-01-01T00:00:00Z' }, { now }).level).toBe('warn');
    const h = assessHealth({ ...fresh, lastRelease: '2025-08-07T00:00:00Z' }, { now });
    expect(h).toEqual({ level: 'warn', reasons: ['seit 14 Monaten kein Release'] });
    // > 24 months and last push 13 months ago (GitHub) → fail
    expect(assessHealth({ ...fresh, lastRelease: '2023-01-01T00:00:00Z', lastCommit: '2025-09-01T00:00:00Z' }, { now }).level).toBe('fail');
    // unknown commit activity is not silently accepted
    expect(assessHealth({ ...fresh, lastRelease: '2023-01-01T00:00:00Z', lastCommit: null, maintained: null }, { now }).level).toBe('warn');
  });

  test('an exception accepts a library until its date, then reports it again', () => {
    const old = { ...fresh, lastRelease: '2023-09-04T00:00:00Z', lastCommit: null, maintained: 0 };
    const exception = { reason: 'Sprachdaten', until: '2027-10' };
    expect(assessHealth(old, { now, exception }).level).toBe('ok');
    expect(assessHealth(old, { now: Date.parse('2027-11-01T00:00:00Z'), exception }).level).toBe('fail');
    expect(assessHealth(old, { now, exception: { reason: 'x' } }).level).toBe('fail');
  });

  test('every exception in vendor.json has a reason and a date', () => {
    for (const [name, e] of Object.entries(vendor)) {
      if (!e.maintenanceException) continue;
      expect(e.maintenanceException.reason, name).toBeTruthy();
      expect(e.maintenanceException.until, name).toMatch(/^\d{4}-(0[1-9]|1[0-2])$/);
    }
  });

  test('vulnerability severity: high, critical and unrated block a new library', () => {
    expect(vulnSeverity({ database_specific: { severity: 'HIGH' } })).toBe('HIGH');
    expect(vulnSeverity({ database_specific: { severity: 'moderate' } })).toBe('MODERATE');
    expect(vulnSeverity({ affected: [{ ecosystem_specific: { severity: 'CRITICAL' } }] })).toBe('CRITICAL');
    expect(vulnSeverity({})).toBe('UNKNOWN');
    expect(['LOW', 'MODERATE', 'HIGH', 'CRITICAL', 'UNKNOWN'].filter(vulnBlocks)).toEqual(['HIGH', 'CRITICAL', 'UNKNOWN']);
  });
});
